<template>
  <main class="iot-room" v-if="room">
    <header class="iot-top">
      <a class="iot-brand" href="/dashboard/room" aria-label="Nhà thông minh, trang chính"><span class="iot-brand-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/></svg></span><span>Nhà thông minh<small>NHÓM 26 · PHÒNG 1</small></span></a>
      <div class="iot-top-right"><span class="iot-status" :class="online ? 'good' : 'waiting'"><i></i>{{ connectionLabel }}</span><a class="iot-help-link" href="#iot-help" @click="helpOpen = true">Cách dùng ↗</a><form action="/logout" method="post"><button class="iot-text-button iot-logout">Đăng xuất</button></form></div>
    </header>
    <div class="iot-heading"><div><span class="iot-eyebrow">MỘT CHẠM, NHÀ TỰ CHĂM</span><h1>Đèn sáng. Phòng mát. Thật dễ.</h1><p>Bật tắt đèn, máy lạnh hoặc để căn phòng tự làm giúp bạn.</p></div><span class="iot-project-tag">BẢN MÔ PHỎNG</span></div>

    <section v-if="!online" class="iot-connect" aria-labelledby="iot-connect-title"><span class="iot-info-icon" aria-hidden="true">i</span><div><h2 id="iot-connect-title">{{ room.status === 'stale' ? 'Phòng đang mất tín hiệu' : 'Kết nối căn phòng để bắt đầu' }}</h2><p>{{ connectionHelp }}</p><button class="iot-text-button" @click="showHelp">Xem cách kết nối →</button></div></section>
    <div v-if="friendlyAlerts.length" class="iot-alert" role="status"><p v-for="alert in friendlyAlerts" :key="alert">{{ alert }}</p></div>

    <div class="iot-overview">
      <section class="iot-experience" aria-labelledby="iot-experience-title">
        <div class="iot-section-label"><span class="iot-step-dot">1</span> BẮT ĐẦU Ở ĐÂY <span v-if="environment.requested" class="iot-running"><i></i>{{ experienceLabel }}</span></div>
        <h2 id="iot-experience-title">{{ experienceHeading }}</h2>
        <p class="iot-experience-copy">{{ experienceCopy }}</p>
        <div v-if="!environment.requested" class="iot-start-area"><button class="iot-primary iot-start" :disabled="!environment.available || environmentBusy" @click="act('environment', true)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 10 7-10 7Z"/></svg>{{ environment.error ? 'Thử bắt đầu lại' : 'Bắt đầu trải nghiệm' }}<span aria-hidden="true">→</span></button><span class="iot-start-note">{{ !online ? 'Kết nối phòng theo hướng dẫn để dùng nút này.' : !environment.available ? 'Cần chạy Wokwi với firmware mới để trải nghiệm.' : 'Chỉ cần bấm một lần. Cùng xem nhà hoạt động nhé.' }}</span></div>
        <div v-else class="iot-occupancy"><span class="iot-control-label">Bây giờ, bạn đang ở đâu?</span><div class="iot-occupancy-buttons" role="group" aria-label="Thử có người hoặc ra khỏi phòng"><button :class="{selected:environment.presence === 1}" :aria-pressed="environment.presence === 1" :disabled="!environment.available || !environment.active || !!environment.error || environmentBusy" @click="act('occupancy',1)"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="7" r="3"/><path d="M6 21v-3a6 6 0 0 1 12 0v3"/></svg>Tôi ở trong phòng</button><button :class="{selected:environment.presence === 0}" :aria-pressed="environment.presence === 0" :disabled="!environment.available || !environment.active || !!environment.error || environmentBusy" @click="act('occupancy',0)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 21H4V3h12v5M13 15h9m-4-4 4 4-4 4M8 12h.01"/></svg>Tôi ra khỏi phòng</button></div><p class="iot-occupancy-expectation">{{ occupancyHint }}</p></div>
        <div class="iot-experience-bottom"><span class="iot-live-dot" :class="{active:environment.active && online}"></span><p role="status">{{ environmentDescription }}</p></div>
        <div class="iot-experience-footer"><span>Dữ liệu mô phỏng · xem thay đổi sau khoảng 1–2 phút</span><div class="iot-experience-controls"><button v-if="environment.error && environment.requested" class="iot-text-button" :disabled="!environment.available" @click="act('environment',true)">Thử lại ngay</button><button v-if="environment.requested || environment.active" class="iot-text-button" @click="act('environment',false)">Dừng trải nghiệm</button></div></div>
      </section>

      <section class="iot-room-view" aria-labelledby="iot-room-view-title" :class="{disconnected:!online}">
        <div class="iot-room-view-top"><h2 id="iot-room-view-title">Căn phòng lúc này</h2><span class="iot-live-label"><i :class="{active:online}"></i>{{ online ? 'Trực tiếp' : 'Chờ kết nối' }}</span></div>
        <div class="iot-room-scene" :class="{'light-on':room.light === 'ON' && online,'ac-on':room.ac === 'ON' && online}">
          <svg class="iot-room-drawing" viewBox="0 0 420 190" fill="none" aria-hidden="true">
            <path d="M40 155V35a10 10 0 0 1 10-10h320a10 10 0 0 1 10 10v120" fill="#f1eee7" stroke="#dbd7cd" stroke-width="2"/><path d="M40 154h340l24 24H16Z" fill="#e3ddd1"/><path d="M40 154h340" stroke="#cbc3b5" stroke-width="2"/>
            <rect x="72" y="45" width="73" height="65" rx="5" fill="#d6e9e8" stroke="#b3cece" stroke-width="3"/><path d="M108.5 46v62M73 77h71" stroke="#fff" stroke-width="3"/><path d="m78 100 19-16 19 14 22-29v35H78Z" fill="#a9c9b7"/>
            <path class="iot-lamp-glow" d="m208 68-55 85h110Z" fill="#f9d370" opacity="0"/><path d="M208 25v26" stroke="#9a8d76" stroke-width="2"/><path class="iot-lampshade" d="M194 50h28l12 20h-52Z" fill="#d7cbb6"/><path d="M199 70a9 9 0 0 0 18 0" fill="#f5e9cb"/>
            <rect class="iot-scene-ac" x="284" y="44" width="66" height="26" rx="6" fill="#fafaf7" stroke="#c5c9c4" stroke-width="2"/><path d="M293 62h48" stroke="#c5c9c4" stroke-width="2"/><g class="iot-cool-air" stroke="#56aaa9" stroke-width="2.5" stroke-linecap="round" opacity="0"><path d="M300 79v13m17-13v21m17-21v13"/></g>
            <rect x="142" y="110" width="128" height="48" rx="10" fill="#6f8f7a"/><rect x="149" y="102" width="53" height="37" rx="9" fill="#91ad93"/><rect x="207" y="102" width="56" height="37" rx="9" fill="#91ad93"/><rect x="132" y="125" width="16" height="30" rx="6" fill="#7e9c84"/><rect x="264" y="125" width="16" height="30" rx="6" fill="#7e9c84"/><path d="M148 158v6m117-6v6" stroke="#786b58" stroke-width="4"/>
            <path d="M321 136v-23m0 14c-21-1-21-15-21-15 18-1 21 15 21 15Zm0-9c0-19 16-23 16-23 4 19-16 23-16 23Z" stroke="#7a9b70" stroke-width="3" fill="#a6bc8d"/><path d="M310 134h23l-4 24h-15Z" fill="#c49b7b"/>
            <g v-if="room.motion === 1 && room.motionFresh && online"><circle cx="211" cy="100" r="12" fill="#e0ac83"/><path d="M195 133v-9a16 16 0 0 1 32 0v9Z" fill="#dfbb70"/><path d="M198 92c1-14 24-14 26 2-8-1-12-4-15-7-2 4-5 5-11 5Z" fill="#665043"/></g>
          </svg><span class="iot-scene-caption">{{ presenceLabel }}</span>
        </div>
        <div class="iot-room-readings"><div :class="{stale:!room.tempFresh || !online}"><span>Nhiệt độ phòng</span><strong>{{ number(room.temp,1) }}<small>°C</small></strong><p>{{ !room.tempFresh || !online ? 'Chưa có số liệu mới' : room.temp > acTarget + .5 ? 'Cao hơn mức bạn muốn' : room.temp < acTarget - .5 ? 'Mát hơn mức bạn muốn' : 'Gần mức bạn muốn' }}</p></div><div class="iot-room-summary"><span class="iot-source-tag">{{ environment.active ? 'Phòng mô phỏng' : 'Cảm biến Wokwi' }}</span><p>{{ environment.active && environment.coolingPercent != null && online ? 'Mức làm lạnh: ' + environment.coolingPercent + '%' : 'Máy lạnh đang đặt ' + acTarget + '°C.' }}</p><span v-if="!online" class="iot-stale-note">Trạng thái thiết bị chờ cập nhật</span></div></div>
      </section>
    </div>

    <section class="iot-device-section" aria-labelledby="iot-devices-title">
      <div class="iot-section-heading"><div><span class="iot-section-label"><span class="iot-step-dot">2</span> MUỐN TỰ BẬT TẮT?</span><h2 id="iot-devices-title">Thiết bị của bạn</h2></div><p>Bấm nút bên dưới để điều khiển từng thiết bị.</p></div>
      <div class="iot-devices"><article v-for="device in devices" :key="device.key" class="iot-device" :class="{on:device.state === 'ON' && online,cooling:device.key === 'ac'}">
        <div class="iot-device-top"><span class="iot-device-icon"><svg v-if="device.key === 'light'" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18h6m-6 3h6M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2Z"/></svg><svg v-else viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="11" rx="3"/><path d="M6 11h12M7 18v2m5-2v4m5-4v2"/></svg></span><div><h3>{{ device.label }}</h3><span class="iot-device-state" :class="{pending:device.pending}">{{ !online ? 'Chờ kết nối' : device.pending ? 'Đang ' + (device.pending === 'ON' ? 'bật' : 'tắt') + '…' : device.state === 'ON' ? 'Đang bật' : device.state === 'OFF' ? 'Đang tắt' : 'Chờ trạng thái' }}</span></div><span class="iot-device-badge" v-if="online && device.state">{{ device.state === 'ON' ? 'BẬT' : 'TẮT' }}</span></div>
        <p class="iot-device-description">{{ device.description }}</p>
        <section v-if="device.key === 'ac'" class="iot-thermostat" aria-labelledby="iot-target-label">
          <div class="iot-target-heading"><label id="iot-target-label">Nhiệt độ bạn muốn</label><span>{{ manualMode ? 'Tự điều khiển' : 'Tự động · Giờ ngủ' }}</span></div>
          <div class="iot-temperature-control" role="group" aria-label="Chỉnh nhiệt độ máy lạnh từ 16 đến 31 độ">
            <button aria-label="Giảm nhiệt độ máy lạnh" :disabled="acTarget <= 16" @click="setTemperature(acTarget - 1)">−</button>
            <output aria-live="polite" aria-label="Nhiệt độ máy lạnh đã đặt">{{ acTarget }}<small>°C</small></output>
            <button aria-label="Tăng nhiệt độ máy lạnh" :disabled="acTarget >= 31" @click="setTemperature(acTarget + 1)">+</button>
          </div>
          <div class="iot-temperature-scale"><span>16°C · Mát hơn</span><span>Ít lạnh hơn · 31°C</span></div>
          <p class="iot-target-note">{{ manualMode ? (room.ac === 'ON' ? 'Máy đang bật, làm mát theo mức bạn chọn.' : 'Bấm Bật máy lạnh để làm mát theo mức này.') : 'Nhà tự bật tắt máy lạnh để giữ quanh mức này khi có người.' }}</p>
          <small class="iot-saved-target">Đã nhớ riêng · {{ manualMode ? 'Tự động' : 'Tự điều khiển' }}: {{ otherTarget }}°C</small>
        </section>
        <div class="iot-actions" :aria-label="'Điều khiển ' + device.label.toLowerCase()"><button :class="{chosen:online && device.state === 'ON'}" :aria-pressed="online && device.state === 'ON'" :disabled="!online || !!device.pending" @click="act(device.key,'ON')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v9m-5-7a8 8 0 1 0 10 0"/></svg>Bật {{ device.label.toLowerCase() }}</button><button :class="{chosen:online && device.state === 'OFF'}" :aria-pressed="online && device.state === 'OFF'" :disabled="!online || !!device.pending" @click="act(device.key,'OFF')">Tắt {{ device.label.toLowerCase() }}</button></div>
      </article></div>
      <p class="iot-manual-hint"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 8v4l3 2"/></svg>{{ room.mode === 'MANUAL' ? 'Bạn đang tự điều khiển. Giữ lệnh đến khi bạn chọn Tự động, kể cả khi phòng vắng.' : 'Bấm bật/tắt để tự điều khiển. Bạn có thể bật đèn trước khi về nhà.' }}<button v-if="room.mode === 'MANUAL'" class="iot-text-button" @click="act('mode','AUTO')">Để nhà tự chăm ngay →</button></p>
    </section>

    <section class="iot-mode-row" aria-labelledby="iot-mode-title"><div class="iot-mode-intro"><span class="iot-section-label"><span class="iot-step-dot">3</span> CHỌN CÁCH NHÀ HOẠT ĐỘNG</span><h2 id="iot-mode-title">{{ modeLabel }}</h2><p>{{ modeDescription }}</p></div><div class="iot-mode-options" role="group" aria-label="Chọn chế độ"><button v-for="mode in modes" :key="mode.value" :aria-label="mode.label" :class="{selected:room.mode === mode.value}" :aria-pressed="room.mode === mode.value" @click="act('mode',mode.value)"><span class="iot-option-check" aria-hidden="true">{{ room.mode === mode.value ? '✓' : '' }}</span><span><strong>{{ mode.label }}</strong><small>{{ mode.hint }}</small></span></button></div></section>
    <a class="iot-voice-link" href="/voice/voice.html"><span class="iot-voice-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-3 0h6"/></svg></span><span><strong>Thích nói hơn bấm?</strong><small>Mở micro rồi nói “bật đèn” hoặc “tắt máy lạnh”.</small></span><span aria-hidden="true">→</span></a>

    <details class="iot-help" id="iot-help" ref="help" :open="helpOpen" @toggle="helpOpen = $event.target.open"><summary><span>Tôi mới dùng, chỉ tôi với</span><span class="iot-summary-extra">3 bước là biết dùng <b aria-hidden="true">+</b></span></summary><div class="iot-help-body"><ol><li><strong>Kết nối căn phòng</strong><p>Mở dự án Wokwi trong VS Code. Bấm <kbd>Ctrl + Shift + B</kbd> để nạp chương trình, rồi <kbd>F1</kbd> → <b>Wokwi: Start Simulator</b>. Giữ mô phỏng chạy đến khi trang này báo “Phòng đã kết nối”.</p></li><li><strong>Bấm “Bắt đầu trải nghiệm”</strong><p>Phòng bắt đầu ở 30°C, có người ở trong. Đèn tự sáng, máy lạnh làm mát về mức Tự động bạn đã đặt. Chỉnh bằng nút − / + ở thẻ Máy lạnh bên dưới. Nhìn nhiệt độ và trạng thái hai thiết bị để xem kết quả.</p></li><li><strong>Thử “Tôi ra khỏi phòng”</strong><p>Khi Tự động, đèn tắt khi phòng báo vắng. Máy lạnh chờ 15 giây rồi tắt. Bấm “Tôi ở trong phòng” để thử lại. Bạn cũng có thể tự bật tắt từng thiết bị, kể cả khi phòng vắng; chọn Tự động để nhà tự chăm lại.</p></li></ol><p class="iot-help-note">Nút “Dừng trải nghiệm” trả về cảm biến chỉnh tay trong Wokwi. Khi đó, đổi nhiệt độ ở DHT22 và bấm PIR → Simulate Motion để báo có người. PIR chỉ nhận chuyển động; ngồi yên cũng có thể bị báo vắng.</p></div></details>
    <details class="iot-demo"><summary><span>Cài đặt thử nghiệm &amp; số liệu</span><span class="iot-summary-extra">Dành cho lúc trình diễn <b aria-hidden="true">+</b></span></summary><div class="iot-demo-inner">
      <p class="iot-advanced-intro">Các tùy chọn này giúp bạn thử nhanh cách căn phòng phản ứng. Không cần chỉnh để dùng các nút ở trên.</p>
      <p class="iot-advanced-intro">Hai biểu đồ bên dưới xem 15 phút gần nhất, theo giờ thực. Giờ thử 14:00 / 23:00 chỉ dùng để thử lịch. Đường nằm ngang nghĩa là số đo không đổi.</p>
      <div class="iot-clock-state" role="status"><span>Giờ căn phòng đang dùng</span><strong>{{ clockLabel }}</strong><p>{{ clockNotice }}</p></div>
      <div class="iot-demo-setting"><div><h3>Chờ ngắn để dễ quan sát</h3><p>Khi tự động: máy lạnh chờ vắng 15 giây nếu bật, 10 phút nếu tắt.<br>Tự điều khiển luôn giữ đến khi bạn đổi chế độ; không bị rút ngắn bởi demo.</p></div><button class="iot-demo-toggle" :class="{selected:room.demo}" :aria-pressed="room.demo" @click="act('demo',!room.demo)">{{ room.demo ? 'Tắt demo nhanh' : 'Bật demo nhanh' }}</button></div>
      <div class="iot-demo-setting"><div><h3>Thử vào ban ngày hoặc ban đêm</h3><p>23:00–06:00 là giờ ngủ. Chọn “Tự động” để áp dụng lịch sau khi đổi giờ.</p></div><div class="iot-segment" role="group" aria-label="Giờ thử nghiệm"><button v-for="clock in clocks" :key="clock.value" :class="{selected:room.clock === clock.value}" :aria-pressed="room.clock === clock.value" @click="act('clock',clock.value)">{{ clock.label }}</button></div></div>
      <div class="iot-metrics"><article :class="{stale:!room.tempFresh || !online}"><span>Độ ẩm</span><strong>{{ number(room.humidity,0) }}<small>%</small></strong><p>Lượng hơi nước trong không khí</p></article><article :class="{stale:!room.luxFresh || !online}"><span>Độ sáng</span><strong>{{ number(room.lux,0) }}<small>lux</small></strong><p>{{ room.lux == null ? 'Chờ cảm biến ánh sáng' : room.lux < 300 ? 'Phòng đang tối' : 'Phòng đủ sáng' }} · đèn bật theo người</p></article></div>
      <div class="iot-last-action"><span>Hoạt động mới nhất</span><p>{{ room.lastAction }}</p><small>Trạng thái đèn và máy lạnh chỉ cập nhật khi thiết bị phản hồi.</small></div><a class="iot-download" href="/api/log.csv" download>Tải lịch sử hoạt động (.csv) <span aria-hidden="true">↓</span></a>
      <section class="iot-storage" aria-labelledby="iot-storage-title"><h3 id="iot-storage-title">Lịch sử đã lưu</h3><p>{{ room.storage?.records?.toLocaleString('vi-VN') || 0 }} bản ghi trong SQLite · dữ liệu còn sau khi khởi động lại.</p>
        <form class="iot-history-filter" @submit.prevent="loadHistory"><label>Loại hoạt động<select v-model="historyEvent" aria-label="Loại hoạt động"><option value="">Tất cả</option><option value="sensor:temp_humid">Nhiệt độ và độ ẩm</option><option value="sensor:motion">Có người / vắng</option><option value="command:light">Lệnh đèn</option><option value="command:ac">Lệnh máy lạnh</option></select></label><label>Từ thời điểm<input type="datetime-local" v-model="historyFrom"></label><button type="submit" class="iot-demo-toggle" :disabled="historyBusy">{{ historyBusy ? 'Đang tải…' : 'Xem lịch sử' }}</button></form>
        <p v-if="historyError" role="alert">{{ historyError }}</p><p v-if="historyLoaded" class="iot-history-note" role="status">{{ historyRows.length ? 'Tối đa 20 bản ghi gần nhất theo bộ lọc.' : 'Chưa có hoạt động khớp bộ lọc.' }}</p>
        <div v-if="historyRows.length" class="iot-history-table" tabindex="0" aria-label="Bảng lịch sử hoạt động"><table><thead><tr><th>Thời gian</th><th>Hoạt động</th><th>Chế độ</th><th>Nhiệt độ</th><th>Đèn</th><th>Máy lạnh</th></tr></thead><tbody><tr v-for="row in historyRows" :key="row.id"><td>{{ new Date(row.timestamp).toLocaleString('vi-VN') }}</td><td>{{ eventLabel(row.event) }}</td><td>{{ row.mode }}</td><td>{{ row.temp == null ? '—' : number(row.temp,1) + '°C' }}</td><td>{{ row.light === 'ON' ? 'Bật' : row.light === 'OFF' ? 'Tắt' : '—' }}</td><td>{{ row.ac === 'ON' ? 'Bật' : row.ac === 'OFF' ? 'Tắt' : '—' }}</td></tr></tbody></table></div>
      </section>
    </div></details>
    <footer class="iot-footer"><span>Nhà thông minh · Nhóm 26</span><span>{{ environment.active ? 'Đang dùng phòng mô phỏng' : 'Đang dùng cảm biến Wokwi' }} · {{ room.demo ? 'Thời gian chờ rút ngắn' : 'Thời gian chờ bình thường' }}</span></footer>
  </main>
  <div v-else class="iot-room iot-loading" role="status"><h1>Đang mở căn phòng của bạn…</h1><p>Chờ một chút để lấy trạng thái thiết bị.</p></div>
</template>

<script>
export default {
  data() { return { helpOpen:false, historyRows:[], historyEvent:'', historyFrom:'', historyBusy:false, historyLoaded:false, historyError:'', clocks:[{value:'real',label:'Giờ thật'},{value:'day',label:'14:00'},{value:'night',label:'23:00'}], modes:[{value:'AUTO',label:'Tự động',hint:'Nhà tự bật tắt giúp bạn'},{value:'MANUAL',label:'Tự điều khiển',hint:'Bạn chọn bật hoặc tắt'},{value:'SLEEP',label:'Giờ ngủ',hint:'Dùng mức của Tự động'}] }; },
  computed: {
    room() { return this.msg?.payload || null; },
    online() { return this.room.status === 'online'; },
    environment() { return this.room.environment || {available:false,active:false,requested:false,supported:false}; },
    manualMode() { return this.room.mode === 'MANUAL'; },
    acTarget() { return this.room.acTarget ?? 25; },
    otherTarget() { return this.room.acSettings?.[this.manualMode ? 'auto' : 'manual'] ?? 25; },
    environmentBusy() { return ['starting','stopping'].includes(this.environment.phase); },
    connectionLabel() { return this.online ? 'Phòng đã kết nối' : this.room.status === 'stale' ? 'Phòng mất tín hiệu' : 'Phòng chưa kết nối'; },
    connectionHelp() { return this.room.status === 'broker_offline' ? 'Giữ dịch vụ Node-RED và mô phỏng Wokwi đang chạy. Trang sẽ tự kết nối lại.' : 'Mở mô phỏng Wokwi trong VS Code và bấm chạy. Các nút điều khiển sẽ sẵn sàng khi phòng kết nối.'; },
    friendlyAlerts() { return (this.room.alerts || []).filter(a => !/broker MQTT|ESP32 đang offline|Chưa có dữ liệu ESP32 mới/.test(a)).map(a => a.replace('Dữ liệu DHT22 đã cũ; tạm dừng rule máy lạnh','Nhiệt độ chưa cập nhật. Máy lạnh tạm dừng tự động; hãy kiểm tra Wokwi.').replace('Dữ liệu PIR đã cũ; tạm dừng rule tự động','Chưa nhận được chuyển động mới. Hãy kiểm tra cảm biến trong Wokwi.')); },
    experienceLabel() { return this.environment.phase === 'running' ? 'Đang trải nghiệm' : this.environment.phase === 'error' ? 'Đang chờ phản hồi' : this.environment.phase === 'paused' ? 'Đang tạm dừng' : 'Đang chuẩn bị'; },
    experienceHeading() { const phase=this.environment.phase; return phase === 'error' ? 'Phòng chưa nhận được yêu cầu' : phase === 'paused' ? 'Trải nghiệm đang tạm dừng' : phase === 'starting' ? 'Đang kết nối trải nghiệm…' : phase === 'stopping' ? 'Đang dừng trải nghiệm…' : phase === 'running' ? 'Nhìn xem, nhà đang tự chăm!' : 'Thử một căn phòng biết tự chăm'; },
    experienceCopy() { return ['error','paused','starting','stopping'].includes(this.environment.phase) ? 'Giữ tab Wokwi đang chạy và hiển thị cạnh trang này. Hệ thống sẽ tự tiếp tục khi nhận được phản hồi.' : this.environment.requested ? 'Thử ra khỏi phòng bên dưới và quan sát đèn, máy lạnh thay đổi.' : 'Có người thì đèn sáng. Máy lạnh sẽ làm mát từ 30°C về mức Tự động đã đặt: ' + (this.room.acSettings?.auto ?? 25) + '°C.'; },
    environmentDescription() { const e = this.environment;
      if (e.phase === 'error') return e.retryIn > 0 ? 'Phòng chưa phản hồi. Tự thử lại sau ' + e.retryIn + ' giây; bạn vẫn có thể dừng trải nghiệm.' : 'Đang chờ Wokwi có dữ liệu mới để tự gửi lại yêu cầu.';
      if (e.phase === 'paused') return e.requested ? 'Chưa có dữ liệu mô phỏng mới. Khi Wokwi chạy lại, trải nghiệm sẽ tự tiếp tục.' : 'Đã yêu cầu dừng. Khi Wokwi kết nối lại, phòng sẽ trở về cảm biến chỉnh tay.';
      if (e.phase === 'starting') return 'Đang chuẩn bị căn phòng… Chờ thiết bị phản hồi.';
      if (e.phase === 'stopping') return 'Đang dừng trải nghiệm và trả về cảm biến Wokwi…';
      if (e.phase === 'running') return e.direction === 'holding' ? 'Đã đạt mức bạn muốn! Máy lạnh đang giữ quanh ' + this.acTarget + '°C.' : e.direction === 'cooling' ? 'Máy lạnh đang làm mát dần về ' + this.acTarget + '°C.' : e.direction === 'warming' ? (this.room.ac === 'ON' ? 'Đã giảm làm lạnh để phòng ấm dần về mức bạn chọn.' : 'Máy lạnh đang tắt. Phòng sẽ ấm dần.') : 'Đang chờ thiết bị phản hồi.';
      return 'Chỉnh nhiệt độ bạn muốn bằng nút − / + ở thẻ Máy lạnh bên dưới.';
    },
    occupancyHint() { if (!this.online) return 'Chờ phòng kết nối lại để thử có người hoặc ra khỏi phòng.'; if (this.room.mode === 'MANUAL') return 'Bạn đang tự điều khiển: đèn và máy lạnh giữ lệnh của bạn dù phòng vắng. Chọn Tự động để nhà tự bật tắt.'; return this.environment.presence === 0 ? 'Đèn sẽ tắt khi nhận tín hiệu vắng. Máy lạnh tắt sau ' + (this.room.demo ? '15 giây' : '10 phút') + '.' : 'Đèn tự bật. Máy lạnh làm mát về khoảng ' + this.acTarget + '°C khi phòng nóng.'; },
    presenceLabel() { return !this.online || !this.room.motionFresh || this.room.motion == null ? 'Chưa biết có người hay không' : this.room.motion ? (this.environment.active ? 'Có người trong phòng' : 'Vừa có chuyển động') : (this.environment.active ? 'Phòng đang vắng' : 'Chưa thấy chuyển động'); },
    clockLabel() { return this.room.clock === 'day' ? '14:00 · Ban ngày (demo)' : this.room.clock === 'night' ? '23:00 · Ban đêm (demo)' : new Date(this.room.timestamp).toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit',hour12:false}) + ' · Giờ thật'; },
    clockNotice() { return this.room.mode === 'MANUAL' ? 'Bạn đang tự điều khiển. Chọn Tự động để nhà chạy theo giờ này.' : this.room.selectedMode === 'SLEEP' ? 'Bạn đã chọn Giờ ngủ. Chọn Tự động để trở lại lịch theo giờ.' : 'Nhà đang tự chạy theo giờ này; giờ ngủ từ 23:00 đến 06:00.'; },
    modeLabel() { return ({AUTO:'Để nhà tự chăm',MANUAL:'Bạn đang tự điều khiển',SLEEP:'Căn phòng đang ở giờ ngủ'})[this.room.mode] || 'Chọn chế độ'; },
    modeDescription() { return this.room.mode === 'MANUAL' ? 'Bạn quyết định bật/tắt, kể cả khi phòng vắng. Chế độ này giữ đến khi bạn chọn Tự động hoặc Giờ ngủ.' : this.room.mode === 'SLEEP' ? 'Đèn theo người. Máy lạnh dùng mức Tự động đã đặt: ' + this.acTarget + '°C. Giờ ngủ cũng chạy theo lịch 23:00–06:00.' : 'Có người thì bật đèn, vắng thì tắt. Máy lạnh tự giữ quanh ' + this.acTarget + '°C. Chỉnh độ mát ngay ở thẻ Máy lạnh.'; },
    devices() { return [
      {key:'light',label:'Đèn phòng',state:this.room.light,pending:this.room.pendingLight,description:!this.online ? 'Kết nối phòng để bật tắt đèn.' : this.room.mode === 'MANUAL' ? 'Giữ theo nút hoặc giọng nói của bạn, kể cả khi phòng vắng.' : 'Tự động bật theo người. Muốn bật trước khi về? Bấm Bật đèn phòng.'},
      {key:'ac',label:'Máy lạnh',state:this.room.ac,pending:this.room.pendingAc,description:!this.online ? 'Kết nối phòng để bật tắt máy lạnh.' : this.room.mode === 'MANUAL' ? 'Giữ theo lệnh của bạn, kể cả khi phòng vắng. Chọn Tự động để chạy theo cảm biến.' : this.room.motion === 0 && this.room.ac === 'ON' && this.room.mode !== 'MANUAL' ? 'Phòng đang vắng. Tự tắt sau ' + this.duration(this.room.acOffIn) + '.' : 'Tự bật tắt theo người và nhiệt độ bạn đã chọn.'}
    ]; }
  },
  methods: {
    async loadHistory() {
      this.historyBusy=true;this.historyError='';
      try {
        const query=new URLSearchParams({limit:'20'});
        if(this.historyEvent)query.set('event',this.historyEvent);
        if(this.historyFrom)query.set('from',new Date(this.historyFrom).toISOString());
        const response=await fetch('/api/history?'+query);
        if(response.status===401){location.assign('/login');return;}
        if(!response.ok)throw new Error('Không tải được lịch sử. Thử lại nhé.');
        this.historyRows=await response.json();this.historyLoaded=true;
      } catch(error) {this.historyError=error.message;}
      finally {this.historyBusy=false;}
    },
    eventLabel(event) {return ({'sensor:temp_humid':'Nhiệt độ / độ ẩm','sensor:motion':'Có người / vắng','sensor:light':'Độ sáng','command:light':'Lệnh đèn','command:ac':'Lệnh máy lạnh','mode':'Đổi chế độ'})[event] || event;},
    act(kind,value) { this.send({topic:'ui/' + kind,payload:value}); },
    setTemperature(value) { this.act(this.manualMode ? 'manualTemperature' : 'autoTemperature', value); },
    showHelp() { this.helpOpen = true; this.$nextTick(() => this.$refs.help.scrollIntoView({behavior:'smooth',block:'start'})); },
    number(value,digits) { return value == null ? '—' : Number(value).toLocaleString('vi-VN',{maximumFractionDigits:digits}); },
    duration(value) { if (value == null) return '—'; const n = Math.max(0,Math.ceil(value)); return n < 60 ? n + ' giây' : Math.floor(n/60) + ' phút' + (n%60 ? ' ' + n%60 + ' giây' : ''); }
  }
};
</script>

