.iot-room-view{border:1px solid var(--line);border-radius:21px;padding:22px 24px 23px;display:flex;flex-direction:column;background:#fffefa;min-width:0}.iot-room-view-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.iot-room-view h2{font-size:15px;font-weight:700;letter-spacing:-.2px}.iot-live-label{display:flex;align-items:center;gap:5px;font-size:10px;color:#8d9588}.iot-live-label i.active{background:#548d63}.iot-room-scene{position:relative;max-width:430px;width:100%;margin:7px auto 0;padding-bottom:14px}.iot-room-scene .iot-room-drawing{width:100%;height:auto;stroke:none;stroke-width:0}.iot-scene-caption{display:table;margin:-1px auto 0;background:#f3f2eb;border:1px solid #e5e4d8;border-radius:20px;padding:4px 11px;color:#7b806e;font-size:10px}.iot-room-scene.light-on .iot-lamp-glow{opacity:.26}.iot-room-scene.light-on .iot-lampshade{fill:#eabf55}.iot-room-scene.ac-on .iot-cool-air{opacity:1}.iot-room-scene.ac-on .iot-scene-ac{stroke:#7eb7b3;fill:#edf9f6}.iot-room-view.disconnected .iot-room-drawing{opacity:.6}.iot-room-readings{display:flex;align-items:center;gap:20px;justify-content:space-between;border-top:1px solid #eeeae0;padding-top:15px;margin-top:auto}.iot-room-readings>div:first-child>span{font-size:11px;color:#7b8176}.iot-room-readings strong{display:block;font-size:40px;line-height:1.2;font-weight:600;letter-spacing:-1.5px;margin:3px 0}.iot-room-readings strong small{font-size:21px;letter-spacing:0;margin-left:4px;font-weight:500}.iot-room-readings p{font-size:11px}.iot-room-summary{max-width:160px}.iot-source-tag{background:#edf1e6;display:inline-block;border-radius:5px;padding:4px 7px;color:#637454;font-size:10px;margin-bottom:7px}.iot-stale-note{display:block;font-size:10px;color:#9a773c;margin-top:6px}.iot-room .stale strong{color:#939c91}
